// Service implements notification use cases.
type Service struct {
	repo ports.NotificationRepository
}

// NewService creates a service with constructor-based DI.
func NewService(repo ports.NotificationRepository) *Service {
	return &Service{repo: repo}
}

// CreateNotification validates the request and atomically persists the
// notification together with an outbox event.
func (s *Service) CreateNotification(ctx context.Context, req domain.CreateNotificationRequest) (*domain.Notification, error) {
	if err := req.Validate(); err != nil {
		return nil, err // *domain.ValidationError
	}

	priority, err := domain.ParsePriority(req.Priority)
	if err != nil {
		return nil, &domain.ValidationError{Field: "priority", Message: err.Error()}
	}

	now := time.Now().UnixMilli()
	id := uuid.New().String()

	n := &domain.Notification{
		ID:        id,
		Message:   req.Message,
		Priority:  priority,
		CreatedAt: now,
	}

	evt := &domain.OutboxEvent{
		ID:            uuid.New().String(),
		AggregateType: domain.AggregateNotification,
		AggregateID:   id,
		EventType:     domain.EventNotificationCreated,
		Payload:       []byte(fmt.Sprintf(`{"id":%q,"message":%q,"priority":%q}`, id, req.Message, priority.String())),
		CreatedAt:     now,
	}

	if err := s.repo.Create(ctx, n, evt); err != nil {
		return nil, fmt.Errorf("creating notification: %w", err)
	}

	return n, nil
}
