// PostgresRepository implements ports.NotificationRepository using pgx.
type PostgresRepository struct {
	pool *pgxpool.Pool
}

func NewPostgresRepository(pool *pgxpool.Pool) *PostgresRepository {
	return &PostgresRepository{pool: pool}
}

func (r *PostgresRepository) Create(ctx context.Context, n *domain.Notification, evt *domain.OutboxEvent) error {
	tx, err := r.pool.BeginTx(ctx, pgx.TxOptions{})
	if err != nil {
		return &domain.InfrastructureError{Op: "BeginTx", Err: err}
	}
	defer func() { _ = tx.Rollback(ctx) }()

	if _, err := tx.Exec(ctx, `
		INSERT INTO notifications (id, message, priority, created_at)
		VALUES ($1, $2, $3, $4)
	`, n.ID, n.Message, n.Priority.String(), n.CreatedAt); err != nil {
		return &domain.InfrastructureError{Op: "InsertNotification", Err: err}
	}

	if _, err := tx.Exec(ctx, `
		INSERT INTO outbox (id, aggregate_type, aggregate_id, event_type, payload, created_at)
		VALUES ($1, $2, $3, $4, $5, $6)
	`, evt.ID, string(evt.AggregateType), evt.AggregateID, string(evt.EventType), evt.Payload, evt.CreatedAt); err != nil {
		return &domain.InfrastructureError{Op: "InsertOutbox", Err: err}
	}

	if err := tx.Commit(ctx); err != nil {
		return &domain.InfrastructureError{Op: "CommitTx", Err: err}
	}

	return nil
}

// Migrate runs the database migrations for tables and indexes.
func (r *PostgresRepository) Migrate(ctx context.Context) error {
	migrations := []string{
		`CREATE TABLE IF NOT EXISTS notifications (
			id TEXT PRIMARY KEY,
			message TEXT NOT NULL,
			priority TEXT NOT NULL,
			created_at BIGINT NOT NULL
		)`,
		`CREATE TABLE IF NOT EXISTS outbox (
			id TEXT PRIMARY KEY,
			aggregate_type TEXT NOT NULL,
			aggregate_id TEXT NOT NULL,
			event_type TEXT NOT NULL,
			payload JSONB NOT NULL,
			created_at BIGINT NOT NULL
		)`,
		// NOTIF-04: Composite index for priority-based queries
		`CREATE INDEX IF NOT EXISTS idx_notifications_priority_created_at
			ON notifications (priority, created_at DESC)`,
	}

	for i, m := range migrations {
		if _, err := r.pool.Exec(ctx, m); err != nil {
			return fmt.Errorf("migration %d: %w", i, err)
		}
	}
	return nil
}
