// PostNotify handles POST /api/notify. Thin: decode -> service -> map error.
func (h *HTTPHandler) PostNotify(w http.ResponseWriter, r *http.Request) {
	var body createNotificationRequest
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "invalid JSON body"})
		return
	}

	req := domain.CreateNotificationRequest{Message: body.Message, Priority: body.Priority}

	result, err := h.svc.CreateNotification(r.Context(), req)
	if err != nil {
		httpError(w, err)
		return
	}

	writeJSON(w, http.StatusCreated, result)
}

func httpError(w http.ResponseWriter, err error) {
	var valErr *domain.ValidationError
	if errors.As(err, &valErr) {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: valErr.Error()})
		return
	}

	var infErr *domain.InfrastructureError
	if errors.As(err, &infErr) {
		slog.Error("infrastructure error", "op", infErr.Op, "err", infErr.Err)
		writeJSON(w, http.StatusInternalServerError, errorResponse{Error: "internal server error"})
		return
	}

	slog.Error("unexpected error", "err", err)
	writeJSON(w, http.StatusInternalServerError, errorResponse{Error: "internal server error"})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(v); err != nil {
