type contextKey string

const correlationIDKey contextKey = "correlation_id"

// CorrelationID returns the correlation ID from the context.
func CorrelationID(ctx context.Context) string {
	v, _ := ctx.Value(correlationIDKey).(string)
	return v
}

// CorrelationIDMiddleware injects or forwards a correlation ID into each
// request context and sets the response header.
func CorrelationIDMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Correlation-ID")
		if id == "" {
			id = uuid.New().String()
		}
		ctx := context.WithValue(r.Context(), correlationIDKey, id)
		w.Header().Set("X-Correlation-ID", id)
		slog.Debug("request", "method", r.Method, "path", r.URL.Path, "correlation_id", id)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

// MethodNotAllowedHandler is used by chi as the MethodNotAllowed handler for NOTIF-05.
func MethodNotAllowedHandler(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
}
