// fakeService implements the service contract for handler tests.
type fakeService struct {
	createFn func(ctx context.Context, req domain.CreateNotificationRequest) (*domain.Notification, error)
}

func (f *fakeService) CreateNotification(ctx context.Context, req domain.CreateNotificationRequest) (*domain.Notification, error) {
	return f.createFn(ctx, req)
}

// serviceAdapter wraps a fakeService to match *application.Service.
type serviceAdapter struct {
	inner *fakeService
}

func (a *serviceAdapter) CreateNotification(ctx context.Context, req domain.CreateNotificationRequest) (*domain.Notification, error) {
	return a.inner.CreateNotification(ctx, req)
}

func TestHTTPHandler_PostNotify_MissingFields(t *testing.T) {
	tests := []struct {
		name       string
		body       map[string]string
		wantStatus int
		wantErrSub string
	}{
		{
			name:       "Missing message field",
			body:       map[string]string{"priority": "low"},
			wantStatus: http.StatusBadRequest,
			wantErrSub: "message is required",
		},
		{
			name:       "Missing priority field",
			body:       map[string]string{"message": "Test"},
			wantStatus: http.StatusBadRequest,
			wantErrSub: "priority is required",
		},
		{
			name:       "Both fields missing",
			body:       map[string]string{},
			wantStatus: http.StatusBadRequest,
			wantErrSub: "message is required",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			svc := &fakeService{
				createFn: func(ctx context.Context, req domain.CreateNotificationRequest) (*domain.Notification, error) {
					err := req.Validate()
					if err != nil {
						return nil, err
					}
					return &domain.Notification{ID: "test-id", Message: req.Message}, nil
				},
			}

			// We need to create a minimal service that uses the fake
			// Since we can't directly inject the fake into the handler's service,
			// we'll test the handler separately with a real service and test the
			// service separately. For the handler test, we'll test the error mapping.

			// Instead, test the handler by wrapping a real service with a fake repo
			repo := &recordingRepo{}
			realSvc := application.NewService(repo)
			h := handlers.NewHTTPHandler(realSvc)

			bodyBytes, _ := json.Marshal(tt.body)
			req := httptest.NewRequest(http.MethodPost, "/api/notify", bytes.NewReader(bodyBytes))
			req.Header.Set("Content-Type", "application/json")
			rec := httptest.NewRecorder()

			h.PostNotify(rec, req)

			if rec.Code != tt.wantStatus {
				t.Errorf("expected status %d, got %d", tt.wantStatus, rec.Code)
			}

			var resp map[string]string
			if err := json.NewDecoder(rec.Body).Decode(&resp); err != nil {
				t.Fatalf("failed to decode response: %v", err)
			}

			if resp["error"] == "" {
				t.Error("expected error message in response")
			}

			// Assert no repository call was made (no insert into DB)
			if repo.called {
				t.Error("expected no repository call on validation failure")
			}
		})
	}
}

func TestHTTPHandler_PostNotify_Success(t *testing.T) {
	repo := &recordingRepo{shouldSucceed: true}
	realSvc := application.NewService(repo)
	h := handlers.NewHTTPHandler(realSvc)

	body := map[string]string{"message": "Hello", "priority": "high"}
	bodyBytes, _ := json.Marshal(body)
	req := httptest.NewRequest(http.MethodPost, "/api/notify", bytes.NewReader(bodyBytes))
	req.Header.Set("Content-Type", "application/json")
	rec := httptest.NewRecorder()

	h.PostNotify(rec, req)

	if rec.Code != http.StatusCreated {
		t.Errorf("expected status %d, got %d", http.StatusCreated, rec.Code)
	}

	var result domain.Notification
	if err := json.NewDecoder(rec.Body).Decode(&result); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}

	if result.ID == "" {
		t.Error("expected non-empty notification ID")
	}
	if result.Message != "Hello" {
		t.Errorf("expected message %q, got %q", "Hello", result.Message)
	}
}

func TestHTTPHandler_PostNotify_InvalidJSON(t *testing.T) {
	repo := &recordingRepo{shouldSucceed: true}
	realSvc := application.NewService(repo)
	h := handlers.NewHTTPHandler(realSvc)

	req := httptest.NewRequest(http.MethodPost, "/api/notify", bytes.NewReader([]byte("{invalid}")))
	req.Header.Set("Content-Type", "application/json")
	rec := httptest.NewRecorder()

	h.PostNotify(rec, req)

	if rec.Code != http.StatusBadRequest {
		t.Errorf("expected status %d, got %d", http.StatusBadRequest, rec.Code)
	}
}

// recordingRepo records whether Create was called.
type recordingRepo struct {
	called         bool
	shouldSucceed  bool
}

func (r *recordingRepo) Create(ctx context.Context, n *domain.Notification, evt *domain.OutboxEvent) error {
	r.called = true
	if !r.shouldSucceed {
		return errors.New("not expected to be called")
	}
	return nil
}
